package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        // offset 0, length 6
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 6));
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "  000123".getBytes();
        // offset 0, length 8
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 8));
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        // Note: buffer[end-1] logic depends on the byte being 0 or ' '
        byte[] buffer = "000123  \0\0".getBytes();
        // Manual construction to ensure NUL bytes are present
        byte[] customBuffer = new byte[10];
        System.arraycopy("000123  ".getBytes(), 0, customBuffer, 0, 8);
        customBuffer[8] = 0;
        customBuffer[9] = 0;

        assertEquals(83L, TarUtils.parseOctal(customBuffer, 0, 10));
    }

    @Test
    public void testParseOctal_StartWithZero() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        // If buffer[start] == 0, it returns 0L immediately
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 5));
    }

    @Test
    public void testParseOctal_LengthLessThanTwoThrowsException() {
        byte[] buffer = "1".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("must be at least 2"));
        }
    }

    @Test
    public void testParseOctal_InvalidOctalDigitThrowsException() {
        byte[] buffer = "000823".getBytes(); // '8' is invalid octal
        try {
            TarUtils.parseOctal(buffer, 0, 6);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Exception message is generated via exceptionMessage helper
        }
    }

    @Test
    public void testParseOctal_InvalidCharacterThrowsException() {
        byte[] buffer = "000A23".getBytes(); // 'A' is invalid
        try {
            TarUtils.parseOctal(buffer, 0, 6);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
        }
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Testing max long range within octal limits
        // 777777777777777777 (octal)
        byte[] buffer = "777777777777777777".getBytes();
        long expected = Long.parseLong("777777777777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_OffsetAndLengthLogic() {
        // Testing that offset and length correctly slice the buffer
        byte[] buffer = "abc000123def";
        // The method uses: int end = offset % length; 
        // WAIT: Looking at the source provided: int end = offset % length;
        // This looks like a potential bug in the provided source code if 'end' is meant to be offset + length.
        // However, I must test the code AS PROVIDED.

        // If offset = 2, length = 5: end = 2 % 5 = 2.
        // If start = 2 and end = 2, the for loop (start < end) won't execute.
        // Let's try to find values where start < end.
        // If offset = 1, length = 10: end = 1 % 10 = 1. Still start == end.
        // In the provided logic: start = offset; end = offset % length;
        // For start < end to be true, offset must be less than (offset % length).
        // This is mathematically impossible for positive integers (x < x % y is impossible).

        // Let's re-examine the provided source carefully:
        // int end = offset % length;
        // int start = offset;
        // if (start < end) ...

        // Since start < end is impossible if end = offset % length, 
        // the loops and the for loop will NEVER execute unless offset is negative (not possible for array index)
        // or if the provided code snippet has a typo and meant end = offset + length.

        // I will write a test case that follows the logic provided. 
        // If the provided code is indeed 'offset % length', the result will likely be 0 or throw.
        // However, I will assume the user wants to test the logic as if it were working, 
        // but I'll provide a test for the 'if (buffer[start] == 0)' branch which is reachable.

        byte[] bufferZero = new byte[] {0, 1, 2, 3};
