    }

    @Test
    public void testParseOctal_AllSpaces() {
        // If the loop 'while (start < end)' is never entered because end <= start,
        // the method will return result = 0.
        byte[] buffer = "      ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 6));
    }
}
